// Root-selected NEW render-only silhouettes. Caller passes pinned selected masks; no placement/floor authority.
export function restoreTargetForeground({rgba,source,camera,location,actorAlpha,actorOrigin,layers}){const restored=new Uint8Array(camera[2]*camera[3]);let count=0;for(const layer of layers){if(layer.mapId!==location.mapId)continue;if(layer.sourceSHA!==location.imageSHA)throw Error('FOREGROUND_SOURCE_PIN_MISMATCH');if(location.foot[1]>=layer.depthY)continue;const [ox,oy]=layer.origin,[w,h]=layer.size;if(!(layer.mask instanceof Uint8Array)||layer.mask.length!==w*h)throw Error('FOREGROUND_MASK_DIMENSION');for(let y=0;y<h;y++)for(let x=0;x<w;x++){if(layer.mask[y*w+x]!==1)continue;const wx=ox+x,wy=oy+y,px=wx-camera[0],py=wy-camera[1],ax=px-actorOrigin[0],ay=py-actorOrigin[1];if(px<0||py<0||px>=camera[2]||py>=camera[3]||ax<0||ay<0||ax>=107||ay>=107||!actorAlpha[ay*107+ax])continue;const d=(py*camera[2]+px)*4,s=(wy*1536+wx)*4;rgba.set(source.subarray(s,s+4),d);restored[d/4]=1;count++}}return{restored,count}}
